import{_ as a,o as t,c as s,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Clustering — Cooperating Nodes, Heartbeats, Leader Election","description":"","frontmatter":{},"headers":[],"relativePath":"system_design/clustering/Clustering.md","filePath":"system_design/clustering/Clustering.md"}'),n={name:"system_design/clustering/Clustering.md"};function i(o,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="clustering-—-cooperating-nodes-heartbeats-leader-election" tabindex="-1">Clustering — Cooperating Nodes, Heartbeats, Leader Election <a class="header-anchor" href="#clustering-—-cooperating-nodes-heartbeats-leader-election" aria-label="Permalink to &quot;Clustering — Cooperating Nodes, Heartbeats, Leader Election&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="what-a-cluster-is" tabindex="-1">What a cluster is <a class="header-anchor" href="#what-a-cluster-is" aria-label="Permalink to &quot;What a cluster is&quot;">​</a></h3><p>A cluster is a group of machines that <strong>cooperate and coordinate to behave as a single logical system</strong>. The important idea is not &quot;multiple servers exist&quot; — it&#39;s that the servers are <em>aware of each other</em> and actively work together: they communicate, coordinate state, detect failures, and often elect leaders.</p><p>Examples: Redis Cluster, Kafka cluster, database clusters, Kubernetes control-plane clusters.</p><h3 id="clustering-vs-load-balancing-—-the-classic-trap" tabindex="-1">Clustering vs load balancing — the classic trap <a class="header-anchor" href="#clustering-vs-load-balancing-—-the-classic-trap" aria-label="Permalink to &quot;Clustering vs load balancing — the classic trap&quot;">​</a></h3><p>A load balancer simply <strong>distributes traffic</strong>; a cluster is about <strong>cooperation between nodes</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Load balancing:                    Clustering:</span></span>
<span class="line"><span>Client → LB → [S1 | S2 | S3]       Node A ⇄ Node B ⇄ Node C</span></span>
<span class="line"><span>(servers may know nothing          (heartbeats, replication,</span></span>
<span class="line"><span> about each other)                  failure detection, leader election)</span></span></code></pre></div><p>The LB&#39;s job: spread traffic, improve throughput, prevent overload. The cluster itself provides functionality beyond serving traffic: exchanging heartbeats, replicating data, detecting failures, electing leaders, coordinating state.</p><h3 id="redis-cluster-example" tabindex="-1">Redis Cluster example <a class="header-anchor" href="#redis-cluster-example" aria-label="Permalink to &quot;Redis Cluster example&quot;">​</a></h3><p>Data is <strong>sharded</strong> across nodes — each shard stores only part of the dataset:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Shard 1 → user IDs 1–1000</span></span>
<span class="line"><span>Shard 2 → user IDs 1001–2000</span></span>
<span class="line"><span>Shard 3 → user IDs 2001–3000</span></span></code></pre></div><p>A request like <code>GET user:1500</code> is routed to the node that owns that shard.</p><p><strong>Replication inside the cluster</strong> — sharding alone is not enough; each shard typically has replicas:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Primary A → Replica A1</span></span>
<span class="line"><span>Primary B → Replica B1</span></span>
<span class="line"><span>Primary C → Replica C1</span></span></code></pre></div><p>The primary handles writes; replicas copy data from the primary, can serve reads (configuration-dependent), and are failover candidates.</p><h3 id="leader-election-and-failover" tabindex="-1">Leader election and failover <a class="header-anchor" href="#leader-election-and-failover" aria-label="Permalink to &quot;Leader election and failover&quot;">​</a></h3><p>If a primary fails, the cluster detects it and <strong>promotes a replica</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Primary A (FAILED) → Replica A1 promoted → new Primary A</span></span></code></pre></div><p>This is leader election — the goal is restoring availability without manual intervention.</p><h3 id="heartbeats" tabindex="-1">Heartbeats <a class="header-anchor" href="#heartbeats" aria-label="Permalink to &quot;Heartbeats&quot;">​</a></h3><p>Clusters determine whether nodes are alive via heartbeats (&quot;I&#39;m alive&quot; messages). If heartbeats stop arriving from a node, the cluster assumes it failed and can trigger failover. Heartbeats are the foundational building block for <strong>failure detection, failover, and leader election</strong>.</p><h3 id="kafka-cluster-example" tabindex="-1">Kafka cluster example <a class="header-anchor" href="#kafka-cluster-example" aria-label="Permalink to &quot;Kafka cluster example&quot;">​</a></h3><p>A Kafka cluster contains multiple brokers. Topics split into partitions; each partition has <strong>one leader broker and one or more followers</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Orders topic, Partition 0:</span></span>
<span class="line"><span>Leader   → Broker 1</span></span>
<span class="line"><span>Follower → Broker 2</span></span>
<span class="line"><span>Follower → Broker 3</span></span></code></pre></div><p>Writes go to the leader; followers replicate from it. If the leader broker fails, a follower is promoted — leader election again.</p><h3 id="the-common-pattern" tabindex="-1">The common pattern <a class="header-anchor" href="#the-common-pattern" aria-label="Permalink to &quot;The common pattern&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Multiple nodes + heartbeats + replication + leader election + failover</span></span></code></pre></div><p>Redis, Kafka, databases, and Kubernetes all implement variations of this same pattern. Implementations differ; the fundamental ideas remain the same.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><p><strong>&quot;Multiple servers behind a load balancer means I have a cluster.&quot;</strong> Not necessarily — if the servers don&#39;t coordinate state, replicate data, exchange heartbeats, or elect leaders, that&#39;s load balancing, not clustering.</p></li><li><p><strong>&quot;Load balancing and clustering are basically the same.&quot;</strong></p><table tabindex="0"><thead><tr><th>Load balancing</th><th>Clustering</th></tr></thead><tbody><tr><td>Distributes traffic</td><td>Coordinates nodes</td></tr><tr><td>Focused on request routing</td><td>Focused on system cooperation</td></tr><tr><td>Servers may be independent</td><td>Nodes actively communicate</td></tr><tr><td>Improves throughput</td><td>Improves availability, coordination, state management</td></tr></tbody></table></li><li><p><strong>&quot;Redis clustering is only about adding more machines.&quot;</strong> No — it involves data sharding, replication, failure detection, replica promotion, and leader election.</p></li><li><p><strong>&quot;Leader election is only a database concept.&quot;</strong> It appears in Redis, Kafka, database clusters, and the Kubernetes control plane.</p></li><li><p><strong>&quot;Heartbeats are just monitoring.&quot;</strong> They&#39;re the core mechanism driving failure detection, failover decisions, and leader election — without them the cluster can&#39;t reliably know whether a node is alive.</p></li></ol><h2 id="performance-characteristics" tabindex="-1">Performance characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance characteristics&quot;">​</a></h2><p><strong>Benefits:</strong> higher availability, automatic failover, better fault tolerance, data distribution across nodes, scaling beyond a single machine.</p><p><strong>Trade-offs:</strong> coordination overhead — nodes must communicate, replicate, exchange heartbeats, and manage leadership changes. The price buys availability and resilience.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><p>All the clustered systems discussed — Redis Cluster, Kafka, database clusters, Kubernetes control plane — use the same broad ideas (cooperating nodes, heartbeats, replication, failover, leader election). The implementation details differ, but the mental model transfers between them.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What is the primary purpose of clustering?</strong> A. Multiple machines cooperate and coordinate to behave as one logical system.</p><p><strong>Q. Load balancing vs clustering?</strong> A. Load balancing distributes traffic; clustering coordinates nodes.</p><p><strong>Q. Why is Redis Cluster a cluster and not just multiple Redis servers?</strong> A. Sharding, replication, failure detection, and failover coordination.</p><p><strong>Q. What is the role of a replica in Redis?</strong> A. It copies data from the primary and can be promoted during failover.</p><p><strong>Q. Why do clusters use heartbeats?</strong> A. To detect failed nodes and trigger failover or leader election.</p><p><strong>Q. How does Kafka use clustering?</strong> A. Each partition has a leader and followers; a follower is promoted if the leader fails.</p><p><strong>Q. What pattern is common across Redis, Kafka, DB clusters, and Kubernetes?</strong> A. Heartbeats + replication + leader election + failover among cooperating nodes.</p>`,44)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
